import {Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useQuery} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';
import {Card,EmptyState,Header,Muted,Screen,useAppTheme} from '@/components/UI';

type Doc={Id:string;Category:string;Title:string;Summary?:string;Visibility:'MEMBERS'|'ADMINS';UpdatedAt:string;FileName?:string;MimeType?:string;SizeBytes?:number};
const folderCategories:Record<string,string[]>={All:['Constitution','Policies','Meeting minutes','Financial reports','Forms','Newsletters','Community rules','Emergency procedures','Archives','Other'],Policies:['Policies','Constitution','Community rules'],Reports:['Meeting minutes','Financial reports','Newsletters'],Forms:['Forms'],Archives:['Archives']};
const formatSize=(value?:number)=>!value?'':value<1048576?`${(value/1024).toFixed(1)} KB`:`${(value/1048576).toFixed(1)} MB`;
export default function DocumentFolder(){const{id,folder}=useLocalSearchParams<{id:string;folder:string}>(),{palette}=useAppTheme(),name=decodeURIComponent(String(folder||'All')),categories=folderCategories[name]||[name];const documents=useQuery<Doc[]>({queryKey:['documents',id],queryFn:async()=>(await api.get(`/communities/${id}/documents`)).data});const rows=(documents.data||[]).filter(document=>name==='All'||categories.includes(document.Category));return <Screen scroll contentStyle={s.page}><Header page title={name==='All'?'All Documents':name} subtitle={`${rows.length} ${rows.length===1?'document':'documents'} in this folder`}/>{documents.isLoading?<Muted>Loading folder…</Muted>:documents.isError?<EmptyState icon="cloud-offline-outline" title="Folder unavailable" body="The documents could not be loaded."/>:rows.length?rows.map(document=><Pressable key={document.Id} accessibilityRole="button" accessibilityLabel={`Open ${document.Title}`} onPress={()=>router.push({pathname:`/community/${id}/document/${document.Id}` as any,params:{title:document.Title}})}><Card style={s.row}><View style={[s.icon,{backgroundColor:palette.primarySoft}]}><Ionicons name="document-text-outline" size={25} color={palette.primary}/></View><View style={s.copy}><Text numberOfLines={2} style={[s.title,{color:palette.text}]}>{document.Title}</Text><Muted numberOfLines={2}>{document.Summary||document.FileName||document.Category}</Muted><Muted>{document.Category}{document.SizeBytes?` · ${formatSize(document.SizeBytes)}`:''} · {new Date(document.UpdatedAt).toLocaleDateString()}</Muted></View><View style={[s.badge,{backgroundColor:document.Visibility==='ADMINS'?palette.warningSoft:palette.primarySoft}]}><Text style={{color:document.Visibility==='ADMINS'?palette.warningText:palette.primary,fontSize:10,fontWeight:'900'}}>{document.Visibility==='ADMINS'?'ADMINS':'MEMBERS'}</Text></View><Ionicons name="chevron-forward" size={19} color={palette.muted}/></Card></Pressable>):<EmptyState icon="folder-open-outline" title="Folder is empty" body="Documents added to this category will appear here."/>}</Screen>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:820,alignSelf:'center',paddingBottom:110},row:{minHeight:92,flexDirection:'row',alignItems:'center',gap:12},icon:{width:50,height:50,borderRadius:14,alignItems:'center',justifyContent:'center'},copy:{flex:1,minWidth:0,gap:3},title:{fontSize:15,fontWeight:'900'},badge:{paddingHorizontal:7,paddingVertical:4,borderRadius:8}});
